UPDATE marketing_task
SET status = 2,
    started_at = COALESCE(started_at, #{now}),
    updated_at = #{now}
WHERE id = #{taskId}
  AND business_type = 2
  AND deleted_at IS NULL
  AND status = 1
  AND task_end_at > #{now}

UPDATE group_pull_marketing_task
SET block_reason = 0,
    resource_status = 3,
    updated_at = #{now}
WHERE marketing_task_id = #{taskId}
  AND resource_status = 2

UPDATE group_pull_marketing_task
SET block_reason = #{blockReason},
    updated_at = #{now}
WHERE marketing_task_id = #{taskId}
  AND resource_status = 2

