SELECT 
FROM group_pull_marketing_execution
WHERE id = #{id}

SELECT id, tenant_id, task_id, account_id, reserved_group_count, joined_group_count,
       created_at, updated_at
FROM group_pull_marketing_account_stat
WHERE task_id = #{taskId}
  AND account_id = #{accountId}

mapper.update:
UPDATE group_pull_marketing_account_stat
SET reserved_group_count = reserved_group_count + 1,
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND account_id = #{accountId}
  AND reserved_group_count + joined_group_count < #{limit}

UPDATE group_pull_marketing_account_stat
SET reserved_group_count = reserved_group_count - 1,
    joined_group_count = joined_group_count + 1,
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND account_id = #{accountId}
  AND reserved_group_count > 0

UPDATE group_pull_marketing_account_stat
SET reserved_group_count = reserved_group_count - 1,
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND account_id = #{accountId}
  AND reserved_group_count > 0

UPDATE group_pull_marketing_execution
SET next_execute_at = #{leaseUntil},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status = #{executionStatus}
  AND current_stage = #{expectedStage}
  AND next_execute_at <= #{now}

UPDATE group_pull_marketing_execution
SET next_execute_at = #{nextExecuteAt},
    failure_reason = CASE
        WHEN #{reason} IS NULL OR #{reason} = '' THEN failure_reason
        ELSE LEFT(CONCAT_WS(';', NULLIF(failure_reason, ''), #{reason}), 255)
    END,
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status = #{executionStatus}
  AND current_stage = #{expectedStage}

UPDATE group_pull_marketing_execution
SET execution_status = #{nextExecutionStatus},
    current_stage = #{nextStage},
    stage_retry_count = 0,
    next_execute_at = #{nextExecuteAt},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status = #{executionStatus}
  AND current_stage = #{expectedStage}

UPDATE group_pull_marketing_execution
SET group_invite_url = #{inviteUrl},
    updated_at = #{now}
WHERE id = #{id}
  AND group_jid = #{groupJid}
  AND group_invite_url IS NULL

UPDATE group_pull_marketing_execution
SET execution_status = 7,
    failure_reason = LEFT(CONCAT_WS(';', NULLIF(failure_reason, ''), #{reason}), 255),
    next_execute_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status IN (1, 2)
  AND current_stage = #{expectedStage}

UPDATE group_pull_marketing_execution_material
SET friend_status = #{status},
    friend_failure_reason = #{reason},
    updated_at = #{now}
WHERE id = #{id}
  AND friend_status = 1

UPDATE group_pull_marketing_execution_material
SET entry_status = #{status},
    entry_failure_reason = #{reason},
    updated_at = #{now}
WHERE id = #{id}
  AND entry_status = 1

UPDATE group_pull_marketing_execution
SET stage_retry_count = #{nextRetryCount},
    next_execute_at = #{nextExecuteAt},
    failure_reason = CASE
        WHEN #{reason} IS NULL OR #{reason} = '' THEN failure_reason
        ELSE LEFT(CONCAT_WS(';', NULLIF(failure_reason, ''), #{reason}), 255)
    END,
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status = #{executionStatus}
  AND current_stage = #{expectedStage}
  AND stage_retry_count = #{expectedRetryCount}

UPDATE group_pull_marketing_execution
SET next_execute_at = #{now} + #{minDelayMillis}
        + FLOOR(RAND() * (
            (#{maxDelayMillis} - #{minDelayMillis}) / 1000 + 1
          )) * 1000,
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND execution_status IN (1, 2)
  AND current_stage = 5
  AND EXISTS (
      SELECT 1
      FROM group_pull_marketing_execution_material relation
      WHERE relation.execution_id = group_pull_marketing_execution.id
        AND relation.entry_status = 1
  )

UPDATE group_pull_marketing_execution_material
SET entry_status = 3,
    entry_failure_reason = #{reason},
    updated_at = #{now}
WHERE execution_id = #{executionId}
  AND entry_status = 1

UPDATE group_pull_marketing_execution
SET marketer_admin_status = #{status},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status IN (1, 2)

UPDATE group_pull_marketing_execution
SET builder_exit_status = #{status},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status IN (1, 2)

UPDATE group_pull_marketing_execution
SET failure_reason = LEFT(CONCAT_WS(';', NULLIF(failure_reason, ''), #{reason}), 255),
    updated_at = #{now}
WHERE id = #{id}

UPDATE group_pull_marketing_execution
SET execution_status = #{terminalStatus},
    current_stage = #{terminalStage},
    failure_reason = CASE
        WHEN #{reason} IS NULL OR #{reason} = '' THEN failure_reason
        ELSE LEFT(CONCAT_WS(';', NULLIF(failure_reason, ''), #{reason}), 255)
    END,
    finished_at = #{finishedAt},
    next_execute_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE id = #{id}
  AND execution_status = #{expectedStatus}
  AND current_stage = #{expectedStage}

UPDATE group_pull_marketing_material material
JOIN group_pull_marketing_execution_material relation
  ON relation.material_id = material.id
 AND relation.execution_id = #{executionId}
 AND relation.entry_status = 2
SET material.status = 3,
    material.current_execution_id = #{executionId},
    material.updated_at = #{now}
WHERE material.status = 2
  AND material.current_execution_id = #{executionId}

UPDATE group_pull_marketing_material material
JOIN group_pull_marketing_execution_material relation
  ON relation.material_id = material.id
 AND relation.execution_id = #{executionId}
 AND relation.entry_status = 2
SET material.status = 4,
    material.current_execution_id = #{executionId},
    material.updated_at = #{now}
WHERE material.status = 2
  AND material.current_execution_id = #{executionId}

UPDATE group_pull_marketing_material material
JOIN group_pull_marketing_execution_material relation
  ON relation.material_id = material.id
 AND relation.execution_id = #{executionId}
 AND relation.entry_status != 2
SET material.status = 1,
    material.current_execution_id = NULL,
    material.updated_at = #{now}
WHERE material.status = 2
  AND material.current_execution_id = #{executionId}

UPDATE account account_row
JOIN account_group target_group ON target_group.id = #{targetGroupId}
                               AND target_group.deleted_at IS NULL
SET account_row.account_group_id = target_group.id,
    account_row.updated_at = #{now}
WHERE account_row.id = #{accountId}
  AND account_row.deleted_at IS NULL
  AND account_row.account_group_id != target_group.id
  AND target_group.marketing_occupancy_task_id IS NULL

UPDATE group_pull_marketing_execution
SET released_at = COALESCE(released_at, #{now}),
    updated_at = #{now}
WHERE id = #{id}
  AND released_at IS NULL

UPDATE group_pull_marketing_execution
SET group_status = 2,
    updated_at = #{now}
WHERE id = #{id}
  AND group_jid IS NOT NULL
  AND group_status = 1

UPDATE group_pull_marketing_execution
SET marketing_target_id = #{targetId},
    updated_at = #{now}
WHERE id = #{id}
  AND execution_status = 3
  AND marketing_target_id IS NULL

UPDATE marketing_task
SET next_round_at = CASE
        WHEN status = 5 THEN #{now}
        ELSE #{now} + send_interval_seconds * 1000
    END,
    updated_at = #{now}
WHERE id = #{taskId}
  AND business_type = 2
  AND status IN (2, 5)
  AND next_round_at IS NULL

UPDATE group_pull_marketing_material
SET status = 1,
    current_execution_id = NULL,
    updated_at = #{now}
WHERE current_execution_id = #{executionId}
  AND status = 2

UPDATE group_pull_marketing_execution
SET released_at = COALESCE(released_at, #{now}),
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND released_at IS NULL

UPDATE group_pull_marketing_task
SET block_reason = 0,
    resource_status = 4,
    updated_at = #{now}
WHERE marketing_task_id = #{taskId}
  AND resource_status = 3
